    Accept a ``LegacyTransaction`` object (returned as-is) or raw
    bytes.

    EIP-2718 states that the first byte distinguishes the format:
    [0x00, 0x7f] is a typed transaction, [0xc0, 0xfe] is a legacy
    transaction (RLP list prefix).
    """
    if isinstance(tx, Bytes):
        if tx[0] == 1:
            return rlp.decode_to(AccessListTransaction, tx[1:])
        elif tx[0] == 2:
            return rlp.decode_to(FeeMarketTransaction, tx[1:])
        elif tx[0] == 3:
            return rlp.decode_to(BlobTransaction, tx[1:])
        elif tx[0] == 4:
            return rlp.decode_to(SetCodeTransaction, tx[1:])
        elif tx[0] == 6:
            return rlp.decode_to(FrameTransaction, tx[1:])
        elif tx[0] >= 0xC0:
            assert tx[0] <= 0xFE
            return rlp.decode_to(LegacyTransaction, tx)
        else:
            raise TransactionTypeError(tx[0])
    else:
        return tx

functions.transactions.validate_transaction:
def validate_transaction(tx: Transaction, sender: Address) -> IntrinsicGasCost:
    """
    Verifies a transaction.

    The gas in a transaction gets used to pay for the intrinsic cost of
    operations, therefore if there is insufficient gas then it would not
    be possible to execute a transaction and it will be declared invalid.

    Additionally, the nonce of a transaction must not equal or exceed the
    limit defined in [EIP-2681].
    In practice, defining the limit as ``2**64-1`` has no impact because
    sending ``2**64-1`` transactions is improbable. It's not strictly
    impossible though, ``2**64-1`` transactions is the entire capacity of the
    Ethereum blockchain at 2022 gas limits for a little over 22 years.

    Also, the code size of a contract creation transaction must be within
    limits of the protocol.

    This function takes a transaction and gas_limit as parameters and
    returns the intrinsic gas costs for the transaction after validation.
    It throws an `InsufficientTransactionGasError` exception if the
    transaction does not provide enough gas to cover the intrinsic cost,
    and a `NonceOverflowError` exception if the nonce overflows.
    It also raises an `InitCodeTooLargeError` if the code
    size of a contract creation transaction exceeds the maximum allowed
    size, and a `PriorityFeeGreaterThanMaxFeeError` if the maximum
    priority fee per gas of a fee market transaction exceeds its maximum
    fee per gas.

    [EIP-2681]: https://eips.ethereum.org/EIPS/eip-2681
    [EIP-7623]: https://eips.ethereum.org/EIPS/eip-7623
    """
    from ..vm.interpreter import MAX_INIT_CODE_SIZE

    assert not isinstance(tx, FrameTransaction)

    if U256(tx.nonce) >= U256(U64.MAX_VALUE):
        raise NonceOverflowError("Nonce too high")

    if tx.to == Bytes0(b"") and len(tx.data) > MAX_INIT_CODE_SIZE:
        raise InitCodeTooLargeError("Code size too large")

    if isinstance(tx, FeeMarketCapableTransaction):
        if tx.max_fee_per_gas < tx.max_priority_fee_per_gas:
            raise PriorityFeeGreaterThanMaxFeeError(
                "priority fee greater than max fee"
            )

    if isinstance(tx, BlobTransaction):
        blob_count = len(tx.blob_versioned_hashes)
        if blob_count == 0:
            raise NoBlobDataError("no blob data in transaction")
        if blob_count > BLOB_COUNT_LIMIT:
            raise BlobCountExceededError(
                f"Tx has {blob_count} blobs. Max allowed: {BLOB_COUNT_LIMIT}"
            )
        for blob_versioned_hash in tx.blob_versioned_hashes:
            if blob_versioned_hash[0:1] != VERSIONED_HASH_VERSION_KZG:
                raise InvalidBlobVersionedHashError(
                    "invalid blob versioned hash"
                )

    if isinstance(tx, (BlobTransaction, SetCodeTransaction)):
        if not isinstance(tx.to, Address):
            raise TransactionTypeContractCreationError(tx)

    if isinstance(tx, SetCodeTransaction):
        if not any(tx.authorizations):
            raise EmptyAuthorizationListError("empty authorization list")

    intrinsic = calculate_intrinsic_cost(tx, sender)
    intrinsic_gas = Uint(intrinsic.execution)
    if intrinsic_gas > tx.gas:
        raise InsufficientTransactionGasError("Insufficient intrinsic gas")
    if intrinsic.calldata_floor > tx.gas:
        raise InsufficientTransactionGasError("Insufficient calldata floor")

    if intrinsic.execution > TX_MAX_GAS_LIMIT:
        raise InsufficientTransactionGasError(
            "Intrinsic execution gas exceeds TX_MAX_GAS_LIMIT"
        )
    if intrinsic.calldata_floor > TX_MAX_GAS_LIMIT:
        raise InsufficientTransactionGasError(
            "Intrinsic calldata floor exceeds TX_MAX_GAS_LIMIT"
        )

    return intrinsic

functions.transactions.check_nonce:
def check_nonce(tx: Transaction, sender_nonce: Uint) -> None:
    """
    Check that the transaction's nonce equals the sender's next nonce.
    """
    if sender_nonce > Uint(tx.nonce):
        raise NonceMismatchError("nonce too low")
    elif sender_nonce < Uint(tx.nonce):
        raise NonceMismatchError("nonce too high")

functions.transactions.chain_id:
def chain_id(tx: Transaction) -> None | U64:
    """
    Extract the chain identifier from a transaction. See [EIP-155].

    [EIP-155]: https://eips.ethereum.org/EIPS/eip-155
    """
    if isinstance(tx, LegacyTransaction):
        if tx.v == 27 or tx.v == 28:
            return None

        if tx.v < U256(35):
            raise InvalidSignatureError("bad v")

        return U64((tx.v - U256(35)) >> U256(1))
    else:
        return tx.chain_id

functions.transactions.recover_sender:
def recover_sender(tx: Transaction) -> Address:
    """
    Extracts the sender address from a transaction.

    The v, r, and s values are the three parts that make up the signature
    of a transaction. In order to recover the sender of a transaction the two
    components needed are the signature (``v``, ``r``, and ``s``) and the
    signing hash of the transaction. The sender's public key can be obtained
    with these two values and therefore the sender address can be retrieved.

    This function takes chain_id and a transaction as parameters and returns
    the address of the sender of the transaction. It raises an
    `InvalidSignatureError` if the signature values (r, s, v) are invalid.
    """
    assert not isinstance(tx, FrameTransaction)

    r, s = tx.r, tx.s
    if U256(0) >= r or r >= SECP256K1N:
        raise InvalidSignatureError("bad r")
    if U256(0) >= s or s > SECP256K1N // U256(2):
        raise InvalidSignatureError("bad s")

    if isinstance(tx, LegacyTransaction):
        v = tx.v
        if v == 27 or v == 28:
            public_key = secp256k1_recover(
                r, s, v - U256(27), signing_hash_pre155(tx)
            )
        else:
            assert v >= U256(35), "call chain_id before recover_sender"
            tx_chain_id = U64((v - U256(35)) >> U256(1))
            v = (v - U256(35)) & U256(1)
            public_key = secp256k1_recover(
                r,
                s,
                v,
                signing_hash_155(tx, tx_chain_id),
            )
    elif isinstance(tx, AccessListTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        public_key = secp256k1_recover(
            r, s, tx.y_parity, signing_hash_2930(tx)
        )
    elif isinstance(tx, FeeMarketTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        public_key = secp256k1_recover(
            r, s, tx.y_parity, signing_hash_1559(tx)
        )
    elif isinstance(tx, BlobTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        public_key = secp256k1_recover(
            r, s, tx.y_parity, signing_hash_4844(tx)
        )
    elif isinstance(tx, SetCodeTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        public_key = secp256k1_recover(
            r, s, tx.y_parity, signing_hash_7702(tx)
        )

    return Address(keccak256(public_key)[12:32])

functions.transactions.get_transaction_hash:
def get_transaction_hash(tx: Bytes | LegacyTransaction) -> Hash32:
    """
    Compute the hash of a transaction.

    This function takes a transaction as a parameter and returns the
    keccak256 hash of the transaction. It can handle both legacy transactions
    and typed transactions (`AccessListTransaction`, `FeeMarketTransaction`,
    etc.).
    """
    assert isinstance(tx, (LegacyTransaction, Bytes))
    if isinstance(tx, LegacyTransaction):
        return keccak256(rlp.encode(tx))
    else:
        return keccak256(tx)

functions.transactions.has_access_list:
def has_access_list(
    tx: Transaction,
) -> TypeGuard[AccessListCapableTransaction]:
    """
    Return whether the transaction has an [EIP-2930]-style access list.

    [EIP-2930]: https://eips.ethereum.org/EIPS/eip-2930
    """
    return isinstance(
        tx,
        AccessListCapableTransaction,
    )

functions.transactions.frame_transaction.compute_f:
def compute_frame_signature_hash(tx: FrameTransaction) -> Hash32:
    """
    Compute the canonical signature hash of a frame transaction.

    The raw `signature` bytes of every entry with an empty `msg` are
    elided before hashing, since a signature over the canonical hash
    cannot commit to its own bytes.
    """
    elided_signatures = []
    for signature in tx.signatures:
        if len(signature.message) == 0:
            elided_signatures.append(replace(signature, signature=Bytes(b"")))
        else:
            elided_signatures.append(signature)

    elided_tx = replace(tx, signatures=tuple(elided_signatures))
    return keccak256(b"\x06" + rlp.encode(elided_tx))

functions.transactions.frame_transaction.validate_:
def validate_frame_transaction(
    tx: FrameTransaction,
) -> FrameTransactionValidation:
    """
    Check the statically determinable validity constraints of a frame
    transaction and derive its gas anchors.

    Constraints on individual fields — frame modes and flags, signature
    schemes, and field lengths — are mostly enforced by their types
    while the transaction is decoded. Checked here instead are the
    nonce and fee-cap upper bounds, which are tighter than the decoded
    types enforce, and the constraints that span several fields.

    A frame transaction has no gas limit field; its two gas anchors are
    derived instead. The per-transaction gas cap of [EIP-7825] bounds
    the transaction's execution dimension — the larger of its intrinsic
    cost plus the frames' execution gas budgets and its calldata floor —
    while state gas budgets are exempt from the cap.

    [EIP-7825]: https://eips.ethereum.org/EIPS/eip-7825
    """
    from . import (
        BLOB_COUNT_LIMIT,
        TX_MAX_GAS_LIMIT,
        VERSIONED_HASH_VERSION_KZG,
    )

    if tx.nonce >= U256(U64.MAX_VALUE):
        raise NonceOverflowError("Nonce too high")

    if tx.fees.max_fee_per_gas > Uint(U256.MAX_VALUE):
        raise FeeOverflowError("Max fee per gas too high")
    if tx.fees.max_priority_fee_per_gas > Uint(U256.MAX_VALUE):
        raise FeeOverflowError("Max priority fee per gas too high")

    if tx.fees.max_fee_per_gas < tx.fees.max_priority_fee_per_gas:
        raise PriorityFeeGreaterThanMaxFeeError(
            "priority fee greater than max fee"
        )

    blob_count = len(tx.blob_versioned_hashes)
    if blob_count == 0 and tx.fees.max_fee_per_blob_gas != U256(0):
        raise InvalidMaxFeePerBlobGasError(
            "max fee per blob gas must be zero without blobs"
        )
    if blob_count > BLOB_COUNT_LIMIT:
        raise BlobCountExceededError(
            f"Tx has {blob_count} blobs. Max allowed: {BLOB_COUNT_LIMIT}"
        )
    for blob_versioned_hash in tx.blob_versioned_hashes:
        if blob_versioned_hash[0:1] != VERSIONED_HASH_VERSION_KZG:
            raise InvalidBlobVersionedHashError("invalid blob versioned hash")

    frame_count = ulen(tx.frames)
    if frame_count < Uint(1) or frame_count > MAX_FRAMES_PER_TX:
        raise FrameCountError(actual=frame_count, maximum=MAX_FRAMES_PER_TX)

    signature_hash = compute_frame_signature_hash(tx)
    resolved_signers = tuple(
        validate_signature(signature, tx.sender, signature_hash)
        for signature in tx.signatures
    )

    has_expiry_verifier_frame = False
    total_frame_gas = Uint(0)
    total_frame_execution_gas = Uint(0)
    total_frame_state_gas = Uint(0)
    for index, frame in enumerate(tx.frames):
        total_frame_execution_gas += Uint(frame.gas_limits.execution)
        total_frame_state_gas += Uint(frame.gas_limits.state)
        total_frame_gas += Uint(frame.gas_limits.execution) + Uint(
            frame.gas_limits.state
        )
        if total_frame_gas > Uint(U64.MAX_VALUE):
            raise InvalidFrameError("total frame gas overflows")

        if frame.mode != FrameMode.SENDER and frame.value != U256(0):
            raise InvalidFrameError("only sender frames can transfer value")

        if FrameFlag.APPROVE_EXECUTION in frame.flags:
            if isinstance(frame.to, Address) and frame.to != tx.sender:
                raise InvalidFrameError(
                    "approve execution frame must target sender"
                )

        if FrameFlag.ATOMIC_BATCH in frame.flags:
            if frame.mode == FrameMode.VERIFY:
                raise InvalidFrameError(
                    "atomic batches cannot contain verify frames"
                )
            if index + 1 >= len(tx.frames):
                raise InvalidFrameError("last frame cannot have atomic flag")
            if tx.frames[index + 1].mode == FrameMode.VERIFY:
                raise InvalidFrameError(
                    "atomic batches cannot contain verify frames"
                )

        # Approval scope is disallowed on every frame of an atomic
        # batch, including its terminating frame. A frame belongs to a
        # batch when it or its predecessor carries the flag. Keeping the
        # approval context constant across a batch means unrolling one
        # can never withdraw an execution approval that later SENDER
        # frames rely on, and whether the transaction sets a payer never
        # depends on a batch outcome.
        in_batch = FrameFlag.ATOMIC_BATCH in frame.flags or (
            index > 0 and FrameFlag.ATOMIC_BATCH in tx.frames[index - 1].flags
        )
        if in_batch and frame.flags & APPROVE_SCOPE_MASK != FrameFlag(0):
            raise InvalidFrameError(
                "atomic batch frames cannot carry approval scope"
            )

        if frame.mode == FrameMode.VERIFY and frame.to == EXPIRY_VERIFIER:
            if has_expiry_verifier_frame:
                raise InvalidFrameError("multiple expiry verifier frames")
            has_expiry_verifier_frame = True
            if frame.flags != FrameFlag(0):
                raise InvalidFrameError("expiry verifier frame with flags")
            if frame.value != U256(0):
                raise InvalidFrameError("expiry verifier frame with value")
            if frame.gas_limits.state != U64(0):
                raise InvalidFrameError("expiry verifier frame with state gas")
            if len(frame.data) != EXPIRY_DATA_LENGTH:
                raise InvalidFrameError(
                    "expiry verifier frame data must be an expiry timestamp"
                )

    intrinsic = calculate_frame_transaction_intrinsic_cost(tx)
    standard_gas_limit = Uint(intrinsic.execution) + total_frame_gas
    max_gas = max(
        standard_gas_limit,
        Uint(intrinsic.calldata_floor) + total_frame_state_gas,
    )

    # The per-transaction gas cap of EIP-7825 bounds the execution
    # dimension alone: the intrinsic cost plus the frames' execution
    # budgets, with the calldata floor checked against the same cap.
    # State gas is bounded only by the encoding limit and the block's
    # state gas capacity.
    execution_gas_cap_usage = max(
        Uint(intrinsic.execution) + total_frame_execution_gas,
        Uint(intrinsic.calldata_floor),
    )
    if execution_gas_cap_usage > TX_MAX_GAS_LIMIT:
        raise TransactionGasLimitExceededError(
            "Derived execution gas limit exceeds TX_MAX_GAS_LIMIT"
        )

    return FrameTransactionValidation(
        intrinsic=intrinsic,
        standard_gas_limit=standard_gas_limit,
        max_gas=max_gas,
        signature_hash=signature_hash,
        resolved_signers=resolved_signers,
    )

functions.vm.gas.calculate_total_blob_gas:
def calculate_total_blob_gas(tx: Transaction) -> U64:
    """
    Calculate the total blob gas for a transaction.

    Parameters
    ----------
    tx :
        The transaction for which the blob gas is to be calculated.

    Returns
    -------
    total_blob_gas: `ethereum.base_types.Uint`
        The total blob gas for the transaction.

    """
    if isinstance(tx, BlobCapableTransaction):
        return GasCosts.PER_BLOB * U64(len(tx.blob_versioned_hashes))
    else:
        return U64(0)

functions.vm.instructions.frame.txparam:
def txparam(evm: Evm) -> None:
    """
    Push transaction-scoped information of the executing frame
    transaction onto the stack, selected by the parameter operand.
    """
    # STACK
    param = pop(evm.stack)

    # GAS
    charge_gas(evm, GasCosts.OPCODE_TXPARAM)

    # OPERATION
    frame_context = frame_transaction_context(evm)
    tx = frame_context.tx

    if param == U256(0x00):
        # The frame transaction's type identifier.
        value = U256(0x06)
    elif param == U256(0x01):
        value = U256(tx.nonce)
    elif param == U256(0x02):
        value = U256.from_be_bytes(tx.sender)
    elif param == U256(0x03):
        value = U256(tx.fees.max_priority_fee_per_gas)
    elif param == U256(0x04):
        value = U256(tx.fees.max_fee_per_gas)
    elif param == U256(0x05):
        value = tx.fees.max_fee_per_blob_gas
    elif param == U256(0x06):
        value = U256(frame_context.max_cost)
    elif param == U256(0x07):
        value = U256(len(tx.blob_versioned_hashes))
    elif param == U256(0x08):
        value = U256.from_be_bytes(frame_context.signature_hash)
    elif param == U256(0x09):
        value = U256(len(tx.frames))
    elif param == U256(0x0A):
        value = U256(frame_context.current_frame_index)
    elif param == U256(0x0B):
        value = U256(len(tx.signatures))
    elif param == U256(0x0C):
        # State gas remaining in the executing frame's pool.
        value = U256(frame_context.state_gas_left)
    else:
        raise InvalidParameter("undefined TXPARAM parameter")

    push(evm.stack, value)

    # PROGRAM COUNTER
    evm.pc += Uint(1)

functions.vm.instructions.frame.frameparam:
def frameparam(evm: Evm) -> None:
    """
    Push frame-scoped information of the chosen frame onto the stack,
    selected by the parameter operand.

    A frame's status and gas usage are read from its receipt, which
    exists only once the frame has completed: requesting them for the
    current or a subsequent frame results in an exceptional halt. The
    receipt values are live, not final — a completed frame's state gas
    usage decreases when a later frame refills a state charge
    attributed to it, and is restored when that refill rolls back.
    """
    # STACK
    frame_index = pop(evm.stack)
    param = pop(evm.stack)

    # GAS
    charge_gas(evm, GasCosts.OPCODE_FRAMEPARAM)

    # OPERATION
    frame_context = frame_transaction_context(evm)
    tx = frame_context.tx
    if frame_index >= U256(len(tx.frames)):
        raise InvalidParameter("frame index out of bounds")
    frame = tx.frames[int(frame_index)]

    if param == U256(0x00):
        value = U256.from_be_bytes(resolve_frame_target(tx, frame))
    elif param == U256(0x01):
        value = U256(frame.gas_limits.execution)
    elif param == U256(0x02):
        value = U256(frame.mode)
    elif param == U256(0x03):
        value = U256(frame.flags)
    elif param == U256(0x04):
        value = U256(len(frame.data))
    elif param == U256(0x05):
        if frame_index >= U256(frame_context.current_frame_index):
            raise InvalidParameter(
                "status of the current or a subsequent frame"
            )
        receipt = frame_context.frame_receipts[int(frame_index)]
        value = U256(receipt.status)
    elif param == U256(0x06):
        value = U256(frame.flags & APPROVE_SCOPE_MASK)
    elif param == U256(0x07):
        if FrameFlag.ATOMIC_BATCH in frame.flags:
            value = U256(1)
        else:
            value = U256(0)
    elif param == U256(0x08):
        value = frame.value
    elif param == U256(0x09):
        value = U256(frame.gas_limits.state)
    elif param == U256(0x0A):
        if frame_index >= U256(frame_context.current_frame_index):
            raise InvalidParameter(
                "gas usage of the current or a subsequent frame"
            )
        receipt = frame_context.frame_receipts[int(frame_index)]
        value = U256(receipt.gas_used.execution)
    elif param == U256(0x0B):
        if frame_index >= U256(frame_context.current_frame_index):
            raise InvalidParameter(
                "gas usage of the current or a subsequent frame"
            )
        receipt = frame_context.frame_receipts[int(frame_index)]
        value = U256(receipt.gas_used.state)
    else:
        raise InvalidParameter("undefined FRAMEPARAM parameter")

    push(evm.stack, value)

    # PROGRAM COUNTER
    evm.pc += Uint(1)

functions.vm.precompiled_contracts.alt_bn128.alt_b:
def alt_bn128_pairing_check(evm: Evm) -> None:
    """
    The ALT_BN128 pairing check precompiled contract.

    Parameters
    ----------
    evm :
        The current EVM frame.

    """
    data = evm.call_data

    # GAS
    charge_gas(
        evm,
        ExecutionGas(
            GasCosts.PRECOMPILE_ECPAIRING_PER_POINT * (ulen(data) // Uint(192))
            + GasCosts.PRECOMPILE_ECPAIRING_BASE
        ),
    )

    # OPERATION
    if len(data) % 192 != 0:
        raise OutOfGasError
    result = FQ12.one()
    for i in range(len(data) // 192):
        try:
            p = bytes_to_g1(buffer_read(data, U256(192 * i), U256(64)))
            q = bytes_to_g2(buffer_read(data, U256(192 * i + 64), U256(128)))
        except InvalidParameter as e:
            raise OutOfGasError from e
        if not is_inf(multiply(p, curve_order)):
            raise OutOfGasError
        if not is_inf(multiply(q, curve_order)):
            raise OutOfGasError

        result *= pairing(q, p)

    if result == FQ12.one():
        evm.output = U256(1).to_be_bytes32()
    else:
        evm.output = U256(0).to_be_bytes32()

functions.vm.precompiled_contracts.bls12_381._byte:
def _bytes_to_g1_cached(
    data: bytes,
    subgroup_check: bool = False,
) -> Point3D[FQ]:
    """
    Internal cached version of `bytes_to_g1` that works with hashable `bytes`.
    """
    if len(data) != 128:
        raise InvalidParameter("Input should be 128 bytes long")

    x = bytes_to_fq(data[:64])
    y = bytes_to_fq(data[64:])

    if x >= FQ.field_modulus:
        raise InvalidParameter("x >= field modulus")
    if y >= FQ.field_modulus:
        raise InvalidParameter("y >= field modulus")

    z = 1
    if x == 0 and y == 0:
        z = 0
    point = FQ(x), FQ(y), FQ(z)

    if not is_on_curve(point, b):
        raise InvalidParameter("G1 point is not on curve")

    if subgroup_check and not is_inf(bls12_multiply(point, curve_order)):
        raise InvalidParameter("Subgroup check failed for G1 point.")

    return point

def _bytes_to_g2_cached(
    data: bytes,
    subgroup_check: bool = False,
) -> Point3D[FQ2]:
    """
    Internal cached version of `bytes_to_g2` that works with hashable `bytes`.
    """
    if len(data) != 256:
        raise InvalidParameter("G2 should be 256 bytes long")

    x = bytes_to_fq2(data[:128])
    y = bytes_to_fq2(data[128:])

    z = (1, 0)
    if x == FQ2((0, 0)) and y == FQ2((0, 0)):
        z = (0, 0)

    point = x, y, FQ2(z)

    if not is_on_curve(point, b2):
        raise InvalidParameter("Point is not on curve")

    if subgroup_check and not is_inf(bls12_multiply(point, curve_order)):
        raise InvalidParameter("Subgroup check failed for G2 point.")

    return point

dataclasses.fork_types.StateGasPerByte:
class StateGasPerByte:
    """
    State gas charged per byte of state growth, per [EIP-8037].

    A rate, not an amount: deliberately not a `Uint`, since adding a rate to
    a gas amount is meaningless. Multiplying it by a byte count, in either
    operand order, yields a `StateGas`.

    [EIP-8037]: https://eips.ethereum.org/EIPS/eip-8037
    """

    rate: Uint

    def __mul__(self, num_bytes: Uint) -> StateGas:
        """Return the state gas for `num_bytes` charged at this rate."""
        return StateGas(self.rate * num_bytes)

    def __rmul__(self, num_bytes: Uint) -> StateGas:
        """Return the state gas for `num_bytes` charged at this rate."""
        return StateGas(self.rate * num_bytes)
